// Letterhead artwork pack (header / footer / stamp images you supplied).
//
// Applied ONCE per database on server start (see applyLetterheadPack below):
//   - If a letterhead with the same short code (or same name) already exists, only its
//     header / footer / stamp images are replaced. Name, numbering code, colour,
//     documents and payments are never touched.
//   - If it does not exist (e.g. it was deleted), it is created, and default document-type
//     mappings are added only where none exist yet.
// To re-apply after replacing the images below, change PACK_KEY (e.g. ..._v2).

export const PACK_KEY = 'letterhead_pack_v1';

export const LETTERHEAD_PACK = [
  {
    name: "Vishwa Infra Solutions India Pvt Ltd",
    code: "VIS",
    color: "#D9691A",
    header_data: "data:image/jpeg;base64,",
    footer_data: "data:image/jpeg;base64,",
    stamp_data: "data:image/png;base64,",
    default_for: ["GST INVOICE", "QUOTATION", "REPAIR BILL"]
  },
  {
    name: "Roylance Enterprises",
    code: "RE",
    color: "#0B63A8",
    header_data: "data:image/jpeg;base64,",
    footer_data: "data:image/jpeg;base64,",
    stamp_data: "data:image/png;base64,",
    default_for: []
  },
];

/** Minimal shape of the better-sqlite3 database used here (kept loose so it never breaks the build). */
export function applyLetterheadPack(db: any): { updated: string[]; created: string[] } {
  const result = { updated: [] as string[], created: [] as string[] };
  db.exec('CREATE TABLE IF NOT EXISTS app_meta(key TEXT PRIMARY KEY, value TEXT)');
  if (db.prepare('SELECT 1 AS x FROM app_meta WHERE key=?').get(PACK_KEY)) return result;

  const find = db.prepare("SELECT id FROM letterheads WHERE UPPER(COALESCE(code,''))=UPPER(?) OR LOWER(name)=LOWER(?) ORDER BY id LIMIT 1");
  const update = db.prepare("UPDATE letterheads SET header_data=?, footer_data=?, stamp_data=?, code=COALESCE(NULLIF(code,''),?), color=COALESCE(NULLIF(color,''),?), active=1 WHERE id=?");
  const insert = db.prepare('INSERT INTO letterheads(name,code,color,header_data,stamp_data,footer_data) VALUES(?,?,?,?,?,?)');
  const mapIfMissing = db.prepare('INSERT OR IGNORE INTO letterhead_mappings(doc_type,letterhead_id) VALUES(?,?)');

  for (const lh of LETTERHEAD_PACK) {
    const row = find.get(lh.code, lh.name);
    if (row) {
      update.run(lh.header_data, lh.footer_data, lh.stamp_data, lh.code, lh.color, row.id);
      result.updated.push(lh.name);
    } else {
      const r = insert.run(lh.name, lh.code, lh.color, lh.header_data, lh.stamp_data, lh.footer_data);
      for (const t of lh.default_for) mapIfMissing.run(t, r.lastInsertRowid);
      result.created.push(lh.name);
    }
  }
  db.prepare('INSERT OR REPLACE INTO app_meta(key,value) VALUES(?,?)').run(PACK_KEY, new Date().toISOString());
  return result;
}
